static bool ff_read_layout_has_available_ds ( struct pnfs_layout_segment * lseg ) { struct nfs4_ff_layout_mirror * mirror ; struct nfs4_deviceid_node * devid ; u32 idx ; for ( idx = 0 ; idx < FF_LAYOUT_MIRROR_COUNT ( lseg ) ; idx ++ ) { mirror = FF_LAYOUT_COMP ( lseg , idx ) ; if ( mirror ) { if ( IS_ERR ( mirror -> mirror_ds ) ) { continue ; } devid = & mirror -> mirror_ds -> id_node ; if ( ! nfs4_test_deviceid_unavailable ( devid ) ) { return true ; } } } return false ; } 